class _FamilyParentGuard:
    """Serialise family-shaping operations over one family parent dir.

    Saves, loads, verifies, forks, merges and deletions do not take this
    guard -- only folds (single-chain or family) and family import/export
    do -- so ordinary chain traffic keeps flowing while maintenance work
    serialises: a family fold blocks here until any single-chain fold of a
    sibling member finishes, and a single-chain fold blocks while a family
    fold is active.  On platforms without ``fcntl`` the in-process family
    lock provides the same guarantee within the process.

    The blocking flock (used by a fold entering the critical section) and
    the non-blocking "is anyone there" probe (used by a family import or
    export, which instead waits for every member's own fold outside this
    guard) are the same lock: any holder, blocking or idle-only, keeps the
    other kind out.
    """

    def __init__(self, parent, idle_only=False):
        self._parent = os.path.abspath(parent)
        self._idle_only = idle_only
        self._fd = None
        self._thread_lock = None

    @classmethod
    def idle(cls, parent):
        """Enter only when no fold/import/export is active over *parent*."""
        return cls(parent, idle_only=True)

    @property
    def parent(self):
        return self._parent

    def __enter__(self):
        if fcntl is None:
            self._thread_lock = _family_dir_lock(self._parent)
            if self._idle_only:
                acquired = self._thread_lock.acquire(blocking=False)
                if not acquired:
                    raise _FamilyBusy(self._parent)
            else:
                self._thread_lock.acquire()
            return self
        fd = os.open(_family_lease_path(self._parent), os.O_RDWR | os.O_CREAT, 0o644)
        try:
            flags = fcntl.LOCK_EX
            if self._idle_only:
                flags |= fcntl.LOCK_NB
            try:
                fcntl.flock(fd, flags)
            except OSError as exc:
                if self._idle_only and exc.errno in (
                    errno.EWOULDBLOCK,
                    errno.EAGAIN,
                    errno.EACCES,
                ):
                    os.close(fd)
                    raise _FamilyBusy(self._parent) from None
                raise
        except BaseException:
            os.close(fd)
            raise
        self._fd = fd
        return self

    def __exit__(self, *exc_info):
        if self._fd is not None:
            fd = self._fd
            self._fd = None
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            except OSError:
                pass
            os.close(fd)
            # Reclaim the lease file when no fold still uses it (a live
            # family fold always keeps its marker): the flock above is
            # released by close, so an unheld file here is only debris.
            if not os.path.exists(_family_marker_path(self._parent)):
                path = _family_lease_path(self._parent)
                try:
                    probe = os.open(path, os.O_RDONLY)
                    try:
                        try:
                            fcntl.flock(probe, fcntl.LOCK_EX | fcntl.LOCK_NB)
                        except OSError:
                            pass
                        else:
                            os.unlink(path)
                        try:
                            fcntl.flock(probe, fcntl.LOCK_UN)
                        except OSError:
                            pass
                    finally:
                        os.close(probe)
                except OSError:
                    pass
        if self._thread_lock is not None:
            self._thread_lock.release()
            self._thread_lock = None
        return False


