# ---------------------------------------------------------------------------
# Family export / import
#
# Export packs a whole chain family -- every member directory handed in --
# into one self-contained artifact.  Each member's segment file is read
# exactly once; equal byte strings (the hard-linked shared prefix) become
# one deduplicated block, so the artifact stores the shared history once.
# The manifest records the member order, each member's head and, for every
# block, the segment names at which each member reaches it; import
# reconstructs exactly that layout -- same member count, same segment
# positions, same hard-link sharing -- bit for byte.
#
# Both directions are read-only / append-only with respect to the member
# chains: export never writes into a member, and import writes only into a
# private staging parent populated exactly like a fork's staging (segment
# links first, head pointers last), renaming the whole parent over the
# target only once every member is complete.  A hard kill therefore
# leaves either the previous target parent or the fully populated one; an
# interrupted import re-run from scratch is identical to one uninterrupted
# run, and its staging debris is reclaimed by the next family operation
# over that parent.  Export and import run serialised with folds by the
# family parent guard; the members' own directory locks, taken in a
# deadlock-free total order, serialise each member against saves, loads,
# appends, forks, merges and deletions at every step.
# ---------------------------------------------------------------------------


def _family_export_wait_quiescent(members, stores):
    """Roll dead folds forward and wait out live ones for every member.

    Returns the member heads once no member carries a fold marker or a
    live family-fold barrier.  A member directory deleted between calls
    simply drops out of the family.
    """
    heads = {}
    for directory in members:
        if not os.path.isdir(directory):
            continue
        with _DirectoryChainLock(directory):
            store = _DirectoryChainStore(directory)
            _recover_directory_chain(directory, store)
            if _member_fold_busy(directory):
                heads[directory] = None
            else:
                heads[directory] = _read_head_optional(store)
    busy = [directory for directory, head in heads.items() if head is None]
    if busy:
        for directory in busy:
            _wait_for_member_quiescent(directory)
        return _family_export_wait_quiescent(members, stores)
    return heads


def _family_export_snapshot(members):
    """One consistent, quiescent snapshot of every member chain.

    Every member lock is taken together (sorted absolute paths, a
    deadlock-free total order) and held while the heads are read and the
    segment bytes inventoried, so a save, append, fork, merge, deletion or
    compaction cannot move a member between the two.  A missing member
    directory or referenced segment raises FileNotFoundError; a
    truncated/corrupt/out-of-order segment raises ValueError -- both
    before the artifact is written.
    """
    abs_members = [os.path.abspath(path) for path in members]
    ordered = sorted(abs_members)
    while True:
        with contextlib.ExitStack() as stack:
            for directory in ordered:
                if os.path.isdir(directory):
                    stack.enter_context(_DirectoryChainLock(directory))
            stores = {d: _DirectoryChainStore(d) for d in ordered if os.path.isdir(d)}
            for directory, store in stores.items():
                _recover_directory_chain(directory, store)
            busy = [d for d in stores if _member_fold_busy(d)]
            if busy:
                contended = busy
            else:
                contended = []
                heads = {}
                for directory, store in stores.items():
                    head = _read_head_optional(store)
                    if head is None:
                        raise CheckpointError(
                            "chain has no head pointer (no basis segment "
                            f"committed): {directory!r}"
                        )
                    heads[directory] = head
                # Validate every reachable chain and inventory the bytes.
                # A missing referenced segment is FileNotFoundError; any
                # framing/order/shape defect is CheckpointError.
                records = {}  # path -> {segment name: raw bytes}
                for directory, store in stores.items():
                    _sweep_chain_debris(directory, heads[directory])
                    records[directory] = _read_member_segments(
                        store, heads[directory]
                    )
                return abs_members, heads, records
        for directory in contended:
            _wait_for_member_quiescent(directory)


def _read_member_segments(store, head):
    """Read ``seg-0..seg-head`` of one member, validating as a load does."""
    _validate_reachable_chain(store, head)
    records = {}
    for index in range(head + 1):
        name = _segment_name(index)
        records[name] = store.read_segment(name)
    return records


def _build_family_export(members, heads, records):
    """Freeze the inventoried family into the self-contained artifact bytes.

    Distinct segment byte strings become one block each, ordered by the
    first (member, position) that reaches them, so the artifact is a pure
    function of the family: exporting the same family twice produces
    identical bytes.
    """
    blocks = []  # (block_id, raw)
    block_of_hash = {}  # sha256 hex digest -> block id
    segment_entries = []  # one entry per block, in block order
    member_entries = []
    for directory in members:
        if directory not in records:
            raise FileNotFoundError(
                f"incremental checkpoint directory not found: {directory!r}"
            )
        member_reach = []  # [segment name, block id] for seg-0..head
        for index in range(heads[directory] + 1):
            name = _segment_name(index)
            raw = records[directory][name]
            digest = hashlib.sha256(raw).hexdigest()
            block_id = block_of_hash.get(digest)
            if block_id is None:
                block_id = len(blocks)
                block_of_hash[digest] = block_id
                blocks.append((block_id, raw))
                segment_entries.append(
                    {
                        "name": name,
                        "size": len(raw),
                        "crc": zlib.crc32(raw) & 0xFFFFFFFF,
                    }
                )
            else:
                # Every member reaches a shared block at the same numbered
                # slot: a hard-linked prefix preserves positions.  A byte
                # string first seen at one position cannot also be the
                # contents of another position in a sound family.
                if segment_entries[block_id]["name"] != name:
                    raise CheckpointError(
                        "family export rejected: identical segment bytes "
                        f"occupy different positions ({segment_entries[block_id]['name']} "
                        f"and {name}) across the members"
                    )
            member_reach.append(block_id)
        member_entries.append(
            {"name": os.path.basename(directory), "head": heads[directory]}
        )

    manifest = {
        "v": _FAMILY_EXPORT_VERSION,
        "members": member_entries,
        "segments": [
            {"name": entry["name"], "size": entry["size"], "crc": entry["crc"]}
            for entry in segment_entries
        ],
    }
    return _frame_family_export(manifest, [raw for _id, raw in blocks]), {
        (member["name"], member["head"]): True for member in member_entries
    }


def _frame_family_export(manifest, blocks):
    manifest_bytes = json.dumps(
        manifest, ensure_ascii=False, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    body = bytearray()
    body += FAMILY_EXPORT_MAGIC
    body += struct.pack("<I", manifest["v"])
    body += struct.pack("<Q", len(manifest_bytes))
    body += manifest_bytes
    body += struct.pack("<Q", len(blocks))
    crc = zlib.crc32(manifest_bytes)
    for raw in blocks:
        body += struct.pack("<Q", len(raw))
        body += raw
        crc = zlib.crc32(raw, crc)
    body += FAMILY_EXPORT_END_MAGIC
    body += struct.pack("<I", crc & 0xFFFFFFFF)
    return bytes(body)


def export_family(members, target):
    """Pack a whole chain family into one self-contained artifact.

    *members* is the sequence of chain directories belonging to the
    family (its order is preserved in the artifact); *target* is the
    artifact file's destination path.  Shared segments -- the hard-linked
    fork prefix -- are stored once; each member's head and the
    member-owned tail segments are preserved exactly, including their
    positions.  The export advances no member's optimizer step and
    mutates no member; exporting the same family twice produces identical
    bytes.  Members keep saving, loading and appending while the export
    runs: the artifact reads one consistent, quiescent snapshot, and no
    member is ever observed as half a chain.

    A missing member directory or a segment a member's head reaches
    raises FileNotFoundError.  A truncated segment, a missing field, an
    out-of-order segment, members whose shapes or layer order disagree,
    or any structurally invalid artifact input rejects the whole export
    with ValueError -- no member changes by a byte.  An unwritable
    destination directory or a full disk raises OSError; the artifact is
    written through a temp file and atomically renamed, so a process
    killed mid-export leaves only the rejected temp file at *target*.
    """
    if isinstance(members, (str, bytes, os.PathLike)):
        raise TypeError("a chain family must be a sequence of chain directories")
    try:
        members = list(members)
    except TypeError:
        raise TypeError(
            "a chain family must be a sequence of chain directories"
        ) from None
    if not members:
        raise CheckpointError("a chain family needs at least one chain")
    paths = []
    for member in members:
        if not isinstance(member, (str, os.PathLike)):
            raise TypeError("chain family members must be chain directory paths")
        paths.append(os.fspath(member))
    if not isinstance(target, (str, os.PathLike)):
        raise TypeError("export target must be a filesystem path")
    target = os.fspath(target)
    for path in paths:
        if not os.path.isdir(path):
            raise FileNotFoundError(
                f"incremental checkpoint directory not found: {path!r}"
            )
    abs_paths = [os.path.abspath(path) for path in paths]
    if len(set(abs_paths)) != len(abs_paths):
        raise CheckpointError("a chain family must not list a member twice")
    parents = {os.path.dirname(path) for path in abs_paths}
    if len(parents) != 1:
        raise CheckpointError(
            "a family export requires every member directory to live in "
            "the same parent directory"
        )
    parent = parents.pop()
    target_abs = os.path.abspath(target)
    target_parent = os.path.dirname(target_abs)
    if not os.path.isdir(target_parent):
        raise FileNotFoundError(
            f"export destination directory not found: {target_parent!r}"
        )
    _sweep_parent_staging(parent)
    if target_parent != parent:
        _sweep_parent_staging(target_parent)

    with _FamilyParentGuard.idle(parent):
        members_ordered, heads, records = _family_export_snapshot(abs_paths)
        raw, _meta = _build_family_export(members_ordered, heads, records)
    _atomic_write(target_parent, os.path.basename(target_abs), raw)
    return None


def _parse_family_export(raw):
    """Validate and decode a family artifact end to end.

    Returns ``(manifest, blocks)`` where *blocks* maps each block id to
    its raw segment bytes.  Every block's length and CRC and the whole
    manifest are checked, and every segment block is itself validated as
    a basis or delta frame (positions, ordering, basis references,
    shapes and layer order walked exactly like a load), so a torn,
    truncated, reordered or shape-inconsistent artifact is refused in
    full before one member directory is created.
    """
    if not isinstance(raw, (bytes, bytearray, memoryview)):
        raise CheckpointError("family artifact must be bytes")
    data = bytes(raw)
    prefix_len = len(FAMILY_EXPORT_MAGIC) + 4 + 8
    if len(data) < prefix_len:
        raise CheckpointError("family artifact is truncated while reading its header")
    if data[: len(FAMILY_EXPORT_MAGIC)] != FAMILY_EXPORT_MAGIC:
        raise CheckpointError("not a family artifact (bad magic)")
    (version,) = struct.unpack(
        "<I", data[len(FAMILY_EXPORT_MAGIC) : len(FAMILY_EXPORT_MAGIC) + 4]
    )
    if version != _FAMILY_EXPORT_VERSION:
        raise CheckpointError(
            f"unsupported family artifact version {version}; this build "
            f"reads version {_FAMILY_EXPORT_VERSION}"
        )
    (manifest_len,) = struct.unpack(
        "<Q", data[len(FAMILY_EXPORT_MAGIC) + 4 : prefix_len]
    )
    if manifest_len <= 0:
        raise CheckpointError("family artifact manifest length is invalid")
    trailer_len = len(FAMILY_EXPORT_END_MAGIC) + 4
    trailer_pos = data.rfind(FAMILY_EXPORT_END_MAGIC)
    if trailer_pos < 0 or len(data) - trailer_pos != trailer_len:
        raise CheckpointError("family artifact trailer is missing or the file is torn")
    manifest_start = prefix_len
    if manifest_len > trailer_pos - manifest_start:
        raise CheckpointError("family artifact manifest overruns the block area")
    manifest_bytes = data[manifest_start : manifest_start + manifest_len]
    (stored_crc,) = struct.unpack("<I", data[trailer_pos + len(FAMILY_EXPORT_END_MAGIC) :])

    try:
        manifest = json.loads(manifest_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CheckpointError(f"family artifact manifest is invalid: {exc}") from exc
    if not isinstance(manifest, dict) or set(manifest) != _FAMILY_MANIFEST_KEYS:
        raise CheckpointError(
            "family artifact manifest must be an object with exactly the "
            f"fields {sorted(_FAMILY_MANIFEST_KEYS)}"
        )
    if manifest["v"] != version:
        raise CheckpointError("family artifact manifest version does not match its frame")
    members = manifest["members"]
    segments = manifest["segments"]
    if not isinstance(members, list) or not members:
        raise CheckpointError("family artifact must name at least one member")
    if not isinstance(segments, list) or not segments:
        raise CheckpointError("family artifact must carry at least one segment block")

    block_start = manifest_start + manifest_len
    (block_count,) = struct.unpack("<Q", data[block_start : block_start + 8])
    if block_count != len(segments):
        raise CheckpointError(
            "family artifact block count does not match its segment inventory"
        )
    pos = block_start + 8
    blocks = {}
    running_crc = zlib.crc32(manifest_bytes)
    for block_id, entry in enumerate(segments):
        _exact_keys(entry, _FAMILY_SEGMENT_KEYS, f"family segment entry {block_id}")
        name = entry["name"]
        if _segment_index(name) is None:
            raise CheckpointError(
                f"family segment entry {block_id} names a bad segment file {name!r}"
            )
        size = entry["size"]
        if isinstance(size, bool) or not isinstance(size, int) or size <= 0:
            raise CheckpointError(
                f"family segment entry {block_id} ({name}) has an invalid size"
            )
        crc_value = entry["crc"]
        if isinstance(crc_value, bool) or not isinstance(crc_value, int) or not (
            0 <= crc_value <= 0xFFFFFFFF
        ):
            raise CheckpointError(
                f"family segment entry {block_id} ({name}) has an invalid crc"
            )
        if pos + 8 > trailer_pos:
            raise CheckpointError(
                f"family artifact is truncated before segment block {block_id} ({name})"
            )
        (raw_len,) = struct.unpack("<Q", data[pos : pos + 8])
        pos += 8
        if raw_len != size or pos + size > trailer_pos:
            raise CheckpointError(
                f"family artifact segment block {block_id} ({name}) is truncated "
                "or its length disagrees with the manifest"
            )
        chunk = data[pos : pos + size]
        pos += size
        actual_crc = zlib.crc32(chunk) & 0xFFFFFFFF
        if actual_crc != crc_value:
            raise CheckpointError(
                f"family artifact segment block {block_id} ({name}) fails its CRC"
            )
        running_crc = zlib.crc32(chunk, running_crc)
        blocks[block_id] = chunk
    if pos != trailer_pos:
        raise CheckpointError("family artifact has trailing or misaligned block bytes")
    if (running_crc & 0xFFFFFFFF) != stored_crc:
        raise CheckpointError("family artifact CRC mismatch: the file is corrupt or torn")

    _validate_family_manifest_layout(manifest, blocks)
    return manifest, blocks


def _validate_family_manifest_layout(manifest, blocks):
    """Check member/segment structure and walk every member's chain."""
    members = manifest["members"]
    segments = manifest["segments"]
    member_names = set()
    for index, member in enumerate(members):
        _exact_keys(member, _FAMILY_MEMBER_KEYS, f"family member entry {index}")
        name = member["name"]
        if (
            not isinstance(name, str)
            or not name
            or name in ("", ".", "..")
            or os.path.basename(name) != name
            or name in member_names
        ):
            raise CheckpointError(f"family member entry {index} has an invalid name")
        member_names.add(name)
        head = member["head"]
        if isinstance(head, bool) or not isinstance(head, int) or head < 0:
            raise CheckpointError(f"family member {name!r} has an invalid head")
        if head >= len(segments):
            raise CheckpointError(
                f"family member {name!r} head {head} names a block the artifact lacks"
            )
    # The inventory holds one block per distinct segment *file name*; a
    # block's name is the numbered slot every member reaches it at.
    block_names = [entry["name"] for entry in segments]
    if len(set(block_names)) != len(block_names):
        raise CheckpointError("family artifact segment inventory repeats a segment name")

    parsed = {}  # block id -> (segment index, raw)
    basis_ids = [
        block_id
        for block_id, name in enumerate(block_names)
        if _segment_index(name) == _BASIS_INDEX
    ]
    if len(basis_ids) != 1:
        raise CheckpointError(
            "family artifact must contain exactly one basis segment block"
        )
    basis_id = basis_ids[0]
    # Validate every frame at least once, at its declared position.
    for block_id, (name, raw) in enumerate(zip(block_names, blocks.values())):
        index = _segment_index(name)
        if index == _BASIS_INDEX:
            try:
                parse_bytes(raw)
            except CheckpointError as exc:
                raise CheckpointError(
                    f"family artifact basis segment file {name!r} is invalid: {exc}"
                ) from exc
        else:
            try:
                _parse_delta(raw, index)
            except CheckpointError as exc:
                raise CheckpointError(
                    f"family artifact segment file {name!r} is invalid: {exc}"
                ) from exc
        parsed[block_id] = (index, raw)

    # Every member walks 0..head through the inventory: the block at each
    # reach position must be that numbered segment, and the assembled
    # chains must share one shape/layer signature.
    reference_signature = None
    for member in members:
        head = member["head"]
        reach = {}
        for index in range(head + 1):
            expected_name = _segment_name(index)
            try:
                block_id = block_names.index(expected_name)
            except ValueError:
                raise CheckpointError(
                    f"family member {member['name']!r} reaches segment file "
                    f"{expected_name!r}, which the artifact does not contain"
                ) from None
            reach[index] = block_id
        walker = _ChainWalker(blocks[reach[0]])
        for index in range(1, head + 1):
            walker.apply_delta(index, blocks[reach[index]])
        document = walker.document()
        signature = _family_shape_signature(document)
        if reference_signature is None:
            reference_signature = signature
        elif signature != reference_signature:
            raise CheckpointError(
                "family artifact rejected: its members' parameter shapes or "
                "layer order do not agree"
            )


def import_family(artifact, target_parent):
    """Restore a family artifact into chain directories under *target_parent*.

    The artifact is validated in full first; the member directories are
    then populated inside one private staging directory (segment files
    hard-linked per shared block -- the shared history exists once -- and
    each member's ``head`` written last, exactly the fork commit order)
    and the staging directory is renamed over *target_parent* in one
    step, so the members appear as complete chains or not at all.  The
    restored member count, segment positions and shared layout match the
    exported family, and every member's parameters, gradients, optimizer
    state and step count and hidden state restore bit for bit; no
    optimizer step advances.

    Re-running an interrupted import yields a result bit for bit
    identical to one uninterrupted run; a killed import's staging debris
    is reclaimed by the next family operation over the parent.  If
    *target_parent* already holds any chain family member the import
    raises ValueError without changing one byte there.  A missing
    artifact file raises FileNotFoundError; a torn, truncated,
    missing-field, reordered or shape/layer-order-inconsistent artifact
    rejects the whole import with ValueError before anything is written;
    an unwritable parent or a full disk raises OSError.
    """
    if not isinstance(artifact, (str, os.PathLike)):
        raise TypeError("import artifact must be a filesystem path")
    if not isinstance(target_parent, (str, os.PathLike)):
        raise TypeError("import target must be a directory path")
    artifact = os.fspath(artifact)
    target_parent = os.fspath(target_parent)
    if not os.path.isfile(artifact):
        raise FileNotFoundError(f"family artifact file not found: {artifact!r}")
    if os.path.exists(target_parent):
        if not os.path.isdir(target_parent):
            raise CheckpointError(
                f"import target exists but is not a directory: {target_parent!r}"
            )
    parent_abs = os.path.abspath(target_parent)
    with open(artifact, "rb") as fh:
        raw = fh.read()
    manifest, blocks = _parse_family_export(raw)

    if os.path.isdir(parent_abs) and os.listdir(parent_abs):
        raise CheckpointError(
            f"import target already holds a chain family: {parent_abs!r}"
        )
    grandparent = os.path.dirname(parent_abs)
    if not os.path.isdir(grandparent):
        raise FileNotFoundError(
            f"import target's parent directory not found: {grandparent!r}"
        )
    _sweep_parent_staging(grandparent)

    with _FamilyParentGuard.idle(parent_abs):
        if os.path.isdir(parent_abs) and os.listdir(parent_abs):
            raise CheckpointError(
                f"import target already holds a chain family: {parent_abs!r}"
            )
        # Re-validate while the guard is held: an artifact is immutable,
        # so this only re-confirms before the first byte is written.
        _materialize_family_import(parent_abs, grandparent, manifest, blocks)
    return None


def _materialize_family_import(parent_abs, grandparent, manifest, blocks):
    """Populate the staging parent and rename it over the target.

    Runs holding the family parent guard.  The staging parent holds one
    content directory per block (hard-linked into every member that
    reaches it) plus the member directories; member heads are committed
    last, so a killed run leaves only whole segment files and no
    half-populated member is ever reachable.
    """
    block_names = [entry["name"] for entry in manifest["segments"]]
    committed = False
    staging = None
    try:
        staging = tempfile.mkdtemp(
            prefix=_IMPORT_TMP_PREFIX + os.path.basename(parent_abs) + "-",
            dir=grandparent,
        )
        # The shared content store: one file per block, once.
        content_dir = os.path.join(staging, ".blocks")
        os.mkdir(content_dir)
        content_paths = []
        for block_id, raw in blocks.items():
            content_path = os.path.join(content_dir, f"block-{block_id:010d}")
            fd, tmp_path = tempfile.mkstemp(prefix=_TMP_PREFIX, dir=content_dir)
            with os.fdopen(fd, "wb") as fh:
                fh.write(raw)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp_path, content_path)
            content_paths.append(content_path)
        _fsync_directory(content_dir)

        # Member directories; link every reached segment, heads last.
        for member in manifest["members"]:
            member_dir = os.path.join(staging, member["name"])
            os.mkdir(member_dir)
            for index in range(member["head"] + 1):
                name = _segment_name(index)
                block_id = block_names.index(name)
                os.link(
                    content_paths[block_id],
                    os.path.join(member_dir, name),
                )
        for member in manifest["members"]:
            member_dir = os.path.join(staging, member["name"])
            _atomic_write(
                member_dir, _HEAD_NAME, str(member["head"]).encode("ascii")
            )
            _fsync_directory(member_dir)

        # The target parent must not exist (or must be empty) at commit
        # time; re-check inside the guarded section and staging window.
        if os.path.isdir(parent_abs) and os.listdir(parent_abs):
            raise CheckpointError(
                f"import target already holds a chain family: {parent_abs!r}"
            )
        os.makedirs(parent_abs, exist_ok=True)
        if os.listdir(parent_abs):
            raise CheckpointError(
                f"import target already holds a chain family: {parent_abs!r}"
            )
        # Move each member directory into the target parent one rename at
        # a time, members first so a kill leaves either a not-yet-created
        # member (roll-forward on the next import repopulates it) or a
        # complete one; the head-committed staging is the recognisable
        # residue the next family operation sweeps.
        for member in manifest["members"]:
            source = os.path.join(staging, member["name"])
            destination = os.path.join(parent_abs, member["name"])
            os.rename(source, destination)
            _fsync_directory(parent_abs)
        committed = True
    finally:
        if not committed and staging is not None:
            _remove_tree_quietly(staging)
    # Success: drop the now-empty staging (content links and the dir).
    _remove_tree_quietly(staging)
    _fsync_directory(grandparent)


# ---------------------------------------------------------------------------
# In-memory family export / import
#
# The in-memory forms use the exact same manifest/block framing: a family
# of MemoryChain stores packs to one ``bytes`` artifact and unpacks into a
# fresh list of MemoryChain stores with the shared blocks held as one
# object per member slot, mirroring hard-link identity on disk.
# ---------------------------------------------------------------------------


def _memory_family_snapshot(members):
    """One locked, consistent snapshot of a family of memory chains."""
    if isinstance(members, MemoryChain):
        raise TypeError("a chain family must be a sequence of MemoryChains")
    try:
        members = list(members)
    except TypeError:
        raise TypeError(
            "a chain family must be a sequence of MemoryChains"
        ) from None
    if not members:
        raise CheckpointError("a chain family needs at least one chain")
    for member in members:
        if not isinstance(member, MemoryChain):
            raise TypeError("chain family members must be MemoryChains")
    if len(set(id(member) for member in members)) != len(members):
        raise CheckpointError("a chain family must not list a member twice")
    ordered = sorted(members, key=id)
    for member in ordered:
        member._lock.acquire()
    try:
        heads = {}
        records = {}
        for member in members:
            head = _read_head_optional(member)
            if head is None:
                raise CheckpointError(
                    "chain has no head pointer (no basis segment committed)"
                )
            heads[id(member)] = head
            _validate_reachable_chain(member, head)
            records[id(member)] = {
                _segment_name(index): member.read_segment(_segment_name(index))
                for index in range(head + 1)
            }
    finally:
        for member in reversed(ordered):
            member._lock.release()
    return members, heads, records


def export_family_memory(members):
    """Pack a family of :class:`MemoryChain` stores into artifact bytes.

    Same semantics as :func:`export_family`: shared segment bytes are
    stored once (identical blocks become one object reference on
    re-import), every member's head and tail positions are preserved,
    the result is a deterministic pure function of the family and no
    member is mutated or stepped.
    """
    members, heads, records = _memory_family_snapshot(members)
    pseudo_paths = [f"member-{index:010d}" for index in range(len(members))]
    pseudo_records = {
        pseudo_paths[index]: records[id(member)]
        for index, member in enumerate(members)
    }
    pseudo_heads = {
        pseudo_paths[index]: heads[id(member)]
        for index, member in enumerate(members)
    }
    raw, _meta = _build_family_export(
        pseudo_paths, pseudo_heads, pseudo_records
    )
    return raw


def import_family_memory(raw):
    """Restore artifact *raw* into a fresh list of :class:`MemoryChain`.

    The restored family has the same member count, segment positions and
    shared-block identity as the exported one; every member reassembles
    bit for bit to its exported state.  A torn, truncated,
    missing-field, reordered or shape/layer-order-inconsistent artifact
    rejects the whole import with ValueError and returns nothing.
    """
    manifest, blocks = _parse_family_export(raw)
    block_names = [entry["name"] for entry in manifest["segments"]]
    restored = []
    for member in manifest["members"]:
        store = MemoryChain()
        for index in range(member["head"] + 1):
            name = _segment_name(index)
            block_id = block_names.index(name)
            store.write_segment(name, blocks[block_id])
        store.write_head(str(member["head"]).encode("ascii"))
        restored.append(store)
    return restored

